import {importCorrection,MAX_BYTES} from './correction-sidecar.js';
import {createCrop,inspectCropPacket,exportCrop,openPageRaster,validateRegion,MAX_PACKET_BYTES} from './correction-crop.js';
const $=id=>document.getElementById(id);let epoch=0,prepared=null,imageURL=null;
function clear(){epoch++;prepared=null;$('crop-inspection').hidden=true;$('crop-provenance').textContent='';$('crop-preview').removeAttribute('src');if(imageURL)URL.revokeObjectURL(imageURL);imageURL=null;}
const tell=text=>{$('crop-status').textContent=text;};
$('crop-form').addEventListener('input',event=>{if(event.target.id!=='page-view-zoom')clear();});
async function inspect(crop,ticket,originalRaw=null){const blob=new Blob([Uint8Array.from(atob(crop.image.base64),c=>c.charCodeAt(0))],{type:'image/png'});const bitmap=await createImageBitmap(blob);try{if(bitmap.width!==crop.image.width||bitmap.height!==crop.image.height)throw Error('Crop decoder dimensions mismatch');}finally{bitmap.close();}const raw=originalRaw??await exportCrop(crop);if(ticket!==epoch)return;prepared=raw;if(new TextEncoder().encode(prepared).length>MAX_PACKET_BYTES)throw Error('Crop packet exceeds 100 KiB');imageURL=URL.createObjectURL(blob);$('crop-preview').src=imageURL;const shown=structuredClone(crop);shown.inspection={pngStructure:'CHECKED',imageDecode:'CHECKED_BY_BROWSER',imageDigest:'CHECKED',provenanceDigest:originalRaw&&JSON.parse(originalRaw).schema==='ocr.correction-crop.v1'?'LEGACY_NOT_PRESENT':'CHECKED_UNSIGNED_ENVELOPE',processingClaim:'UNVERIFIED_FOR_IMPORTED_PIXELS',identity:'UNAUTHENTICATED',rights:'SELF_ASSERTED',admission:'NOT_PERFORMED'};shown.image.base64='[PNG pixels omitted from this provenance view; included in downloaded packet]';$('crop-provenance').textContent=JSON.stringify(shown,null,2);$('crop-inspection').hidden=false;$('crop-provenance').focus();tell('Inspect the actual crop and source-region reference before downloading. Nothing uploaded.');}
$('crop-form').onsubmit=async event=>{event.preventDefault();clear();const ticket=epoch;try{const sidecar=$('correction-file').files[0],page=$('page-raster').files[0];if(!sidecar||sidecar.size>MAX_BYTES)throw Error('Choose a correction sidecar under 64 KiB');const rightsAssertion=$('rights').value,region={x:Number($('crop-x').value),y:Number($('crop-y').value),width:Number($('crop-width').value),height:Number($('crop-height').value)};const correction=await importCorrection(await sidecar.text());const crop=await createCrop(page,{region,correctionDigest:correction.digest,rightsAssertion});await inspect(crop,ticket);}catch(e){if(ticket===epoch)tell(e.message);}};
$('crop-download').onclick=()=>{if(!prepared)return;const url=URL.createObjectURL(new Blob([prepared],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='correction-crop.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);tell('Crop packet downloaded locally. The source file was not transferred.');};
$('crop-reopen').onchange=async event=>{const file=event.target.files[0];if(!file)return;clear();const ticket=epoch;try{if(file.size>MAX_PACKET_BYTES)throw Error('Choose a crop packet under 100 KiB');const raw=await file.text(),packet=await inspectCropPacket(raw);await inspect(packet.crop,ticket,raw);if(ticket===epoch&&JSON.parse(raw).schema==='ocr.correction-crop.v1')tell('Legacy crop: image digest checked, but provenance has no envelope digest. Original file retained without conversion; inspect its assertions.');}catch(e){if(ticket===epoch)tell(e.message);}finally{event.target.value='';}};

let pageBitmap=null,pageToken=0;
function drawPage(){if(!pageBitmap)return;const canvas=$('page-preview'),scale=Math.min(1,800/pageBitmap.width,800/pageBitmap.height);canvas.width=Math.max(1,Math.round(pageBitmap.width*scale));canvas.height=Math.max(1,Math.round(pageBitmap.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(pageBitmap,0,0,canvas.width,canvas.height);canvas.style.maxWidth='none';canvas.style.width=(Math.min(canvas.width,$('page-preview-scroll').clientWidth)*Number($('page-view-zoom').value)/100)+'px';const r={x:Number($('crop-x').value),y:Number($('crop-y').value),width:Number($('crop-width').value),height:Number($('crop-height').value)};try{validateRegion({width:pageBitmap.width,height:pageBitmap.height},r);ctx.strokeStyle='black';ctx.lineWidth=4;ctx.strokeRect(r.x*scale,r.y*scale,r.width*scale,r.height*scale);ctx.strokeStyle='white';ctx.lineWidth=2;ctx.setLineDash([4,4]);ctx.strokeRect(r.x*scale,r.y*scale,r.width*scale,r.height*scale);$('region-status').textContent='Outlined region: X '+r.x+', Y '+r.y+', width '+r.width+', height '+r.height+' decoded pixels. Inspect before exporting.';}catch(e){$('region-status').textContent=e.message;}}
$('crop-form').addEventListener('input',drawPage);
$('page-raster').onchange=async()=>{const ticket=++pageToken,file=$('page-raster').files[0];if(pageBitmap)pageBitmap.close();pageBitmap=null;$('page-reference').hidden=true;if(!file)return;try{const page=await openPageRaster(file);if(ticket!==pageToken){page.bitmap.close();return;}pageBitmap=page.bitmap;$('page-dimensions').textContent='Decoded page raster: '+page.header.width+' × '+page.header.height+' pixels. Display scaled to fit; coordinates refer to original decoded pixels.';$('page-reference').hidden=false;drawPage();}catch(e){if(ticket===pageToken)tell(e.message);}};

$('page-view-zoom').addEventListener('input',()=>{$('page-view-zoom-value').value=$('page-view-zoom').value+'%';drawPage();});
$('crop-text-size').addEventListener('input',()=>{document.body.style.fontSize=(18*Number($('crop-text-size').value)/100)+'px';$('crop-text-size-value').value=$('crop-text-size').value+'%';drawPage();});
